def match_parens(lst):
    '''Returns "Yes" if either order of concatenation of the two strings forms a balanced parentheses sequence; otherwise returns "No". Raises ValueError if list length is not 2, and TypeError if elements are not strings.'''
    n = len(lst)
    if n != 2:
        raise ValueError("List must have exactly two elements")
    s1, s2 = lst[0], lst[1]
    if not isinstance(s1, str) or not isinstance(s2, str):
        raise TypeError("Elements must be strings")
    total_length = len(s1) + len(s2)
    if total_length % 2 != 0:
        return "No"
    def is_balanced(s):
        count = 0
        for c in s:
            if c == '(':
                count += 1
            elif c == ')':
                count -= 1
                if count < 0:
                    return False
        return count == 0
    if is_balanced(s1 + s2) or is_balanced(s2 + s1):
        return "Yes"
    return "No"

